<?php
/**
 * Initial rule library. Patterns are local data and never call external services.
 *
 * @package JobScamChecker
 */

if ( ! defined( 'ABSPATH' ) ) {
    exit;
}

$rule = static function ( $name, $slug, $type, $pattern, $category, $group, $weight, $explanation, $recommendation, $priority = 100 ) {
    return array(
        'name'           => $name,
        'slug'           => $slug,
        'match_type'     => $type,
        'pattern'        => is_array( $pattern ) ? wp_json_encode( $pattern ) : $pattern,
        'category'       => $category,
        'score_group'    => $group,
        'weight'         => $weight,
        'explanation'    => $explanation,
        'recommendation' => $recommendation,
        'enabled'        => 1,
        'priority'       => $priority,
    );
};

return array(
    $rule( 'Unexpected recruiter contact', 'unexpected-recruiter-contact', 'phrase', array( 'we found your profile', 'came across your profile', 'selected from our recruitment database', 'you have been shortlisted without applying' ), 'communication', 'unsolicited_contact', 8, 'Unexpected contact is common in job scams, especially when the sender cannot explain where you applied.', 'Ask for the job posting and verify the recruiter through the company’s official website.' ),
    $rule( 'WhatsApp recruitment', 'whatsapp-recruitment', 'contextual', array( array( 'whatsapp', 'wa.me' ), array( 'job', 'position', 'recruiter', 'hiring', 'interview' ) ), 'channel', 'messaging_recruitment', 9, 'Scammers often conduct the entire hiring process through personal messaging accounts.', 'Verify the role and recruiter independently before continuing outside a trusted platform.' ),
    $rule( 'Telegram recruitment', 'telegram-recruitment', 'contextual', array( array( 'telegram', 't.me' ), array( 'job', 'position', 'recruiter', 'hiring', 'interview' ) ), 'channel', 'messaging_recruitment', 10, 'Telegram-only recruitment provides limited identity verification and is frequently used in task scams.', 'Contact the employer using independently verified details.' ),
    $rule( 'Move conversation off a job platform', 'move-off-platform', 'contextual', array( array( 'linkedin', 'indeed', 'job board', 'upwork' ), array( 'whatsapp', 'telegram', 'text me', 'personal email', 'continue on' ) ), 'channel', 'off_platform', 9, 'Moving immediately away from a job platform can bypass its safety and reporting controls.', 'Keep early communication on the original platform until the recruiter is verified.' ),
    $rule( 'Immediate hiring', 'immediate-hiring', 'phrase', array( 'hired immediately', 'immediate hiring', 'start immediately without interview', 'you are already hired', 'instant hiring' ), 'hiring', 'instant_hiring', 11, 'Hiring before meaningful screening can indicate that the sender is more interested in money or information than your qualifications.', 'Request a formal interview and verify the hiring manager.' ),
    $rule( 'No interview required', 'no-interview', 'phrase', array( 'no interview required', 'without an interview', 'no interview needed', 'interview is not necessary', 'skip the interview' ), 'hiring', 'no_screening', 14, 'Legitimate employers normally assess candidates before making an offer.', 'Do not provide sensitive documents until you have completed a verifiable hiring process.' ),
    $rule( 'Guaranteed job or income', 'guaranteed-income', 'phrase', array( 'guaranteed income', 'guaranteed earnings', '100% guaranteed', 'guaranteed job', 'guaranteed employment', 'risk-free income' ), 'compensation', 'guaranteed_income', 12, 'Employers cannot normally guarantee earnings without conditions or completed work.', 'Ask for written compensation terms and independently verify the employer.' ),
    $rule( 'Unusually high daily income', 'high-daily-income', 'regex', '/(?:earn|make|income|salary|pay(?:ment)?)\D{0,20}(?:[$£€]\s*)?(?:[3-9]\d{2}|\d{4,})\s*(?:\/|per\s*)?(?:day|daily)/iu', 'compensation', 'unrealistic_income', 16, 'High daily pay for unspecified or simple work is a common lure in employment scams.', 'Compare the pay with similar roles and verify all compensation through official company channels.' ),
    $rule( 'High pay for very little work', 'easy-high-pay', 'contextual', array( array( 'easy work', 'simple work', 'simple task', 'few minutes', '1-2 hours', 'one hour' ), array( 'high income', 'earn', 'make money', 'daily income', 'per day' ) ), 'compensation', 'unrealistic_income', 14, 'Promises of unusually high income for minimal effort are characteristic of task and work-from-home scams.', 'Treat the earnings claim skeptically and verify the underlying business.' ),
    $rule( 'Upfront payment request', 'upfront-payment', 'phrase', array( 'upfront payment', 'pay upfront', 'advance payment required', 'pay before you start', 'send payment first', 'processing payment' ), 'payment', 'upfront_fee', 24, 'Legitimate employers generally do not require candidates to pay before starting work.', 'Do not send money. Verify the employer and role independently.' ),
    $rule( 'Training fee', 'training-fee', 'phrase', array( 'training fee', 'pay for training', 'training payment', 'training charge' ), 'payment', 'employment_fee', 22, 'Mandatory training fees paid to a recruiter are a frequent job-scam warning sign.', 'Do not pay the recruiter. Confirm training arrangements with the employer’s verified HR department.' ),
    $rule( 'Registration or application fee', 'registration-fee', 'phrase', array( 'registration fee', 'application fee', 'processing fee', 'onboarding fee', 'activation fee' ), 'payment', 'employment_fee', 22, 'Charging candidates to apply, register, or activate a job is a common scam pattern.', 'Do not pay and verify the opening on the company’s official careers page.' ),
    $rule( 'Equipment purchase or fee', 'equipment-fee', 'phrase', array( 'equipment fee', 'pay for equipment', 'purchase equipment from our vendor', 'buy equipment from our supplier', 'software fee' ), 'payment', 'equipment_payment', 20, 'Fake employers may demand payment to a preferred vendor for equipment that never arrives.', 'Do not use an unverified vendor or send money; contact the employer through official channels.' ),
    $rule( 'Task deposit', 'task-deposit', 'phrase', array( 'task deposit', 'deposit to unlock tasks', 'deposit usdt to unlock tasks', 'security deposit for tasks', 'deposit before completing', 'prepay the task' ), 'task_scam', 'task_deposit', 25, 'Task scams require deposits and may show invented account balances to encourage further payments.', 'Stop paying and do not attempt to unlock or withdraw an on-screen balance.' ),
    $rule( 'Recharge task language', 'recharge-task', 'phrase', array( 'recharge your account', 'recharge task', 'complete the recharge', 'top up to continue', 'top-up your account', 'combination task', 'lucky order' ), 'task_scam', 'recharge_task', 24, 'Recharge and combination-task language is strongly associated with deposit-based task scams.', 'Do not add funds or cryptocurrency to the platform.' ),
    $rule( 'Product optimization tasks', 'optimization-tasks', 'phrase', array( 'product optimization', 'app optimization', 'data optimization task', 'merchant optimization', 'boost product ranking', 'increase product exposure' ), 'task_scam', 'optimization_task', 18, 'Product optimization jobs often simulate commissions before demanding deposits.', 'Do not deposit funds and verify whether the named company actually offers this work.' ),
    $rule( 'Clicking or rating tasks', 'click-rating-tasks', 'contextual', array( array( 'click', 'like', 'rate', 'rating', 'review' ), array( 'task', 'commission', 'order', 'product', 'hotel' ) ), 'task_scam', 'optimization_task', 15, 'Simple clicking, liking, and rating offers are often used to draw victims into paid task schemes.', 'Never pay to receive another task or withdraw supposed earnings.' ),
    $rule( 'Cryptocurrency payment request', 'cryptocurrency-request', 'phrase', array( 'pay in cryptocurrency', 'send bitcoin', 'send usdt', 'deposit usdt', 'usdt payment', 'crypto wallet', 'deposit crypto', 'bitcoin wallet', 'pay with crypto', 'fee with crypto' ), 'payment', 'irreversible_payment', 26, 'Cryptocurrency transfers are difficult to reverse and are commonly requested by scammers.', 'Do not transfer cryptocurrency to obtain or keep a job.' ),
    $rule( 'Gift card request', 'gift-card-request', 'phrase', array( 'buy gift cards', 'purchase gift card', 'pay with gift cards', 'send gift card codes', 'itunes card', 'google play cards' ), 'payment', 'irreversible_payment', 28, 'A legitimate employer will not require job candidates to pay with gift cards.', 'Do not purchase or share gift card codes.' ),
    $rule( 'Fake-check instructions', 'fake-check', 'phrase', array( 'mobile deposit the check', 'deposit the attached check', 'check for office equipment', 'keep part of the check', 'send the remaining funds', 'forward the balance', 'cashier check for equipment' ), 'fake_check', 'fake_check', 30, 'Fake-check scams exploit the delay before a bank discovers that a deposited check is invalid.', 'Do not spend or forward check proceeds; contact your bank using its official number.' ),
    $rule( 'Bank account information request', 'bank-account-request', 'phrase', array( 'send your bank account details', 'provide bank login', 'online banking username', 'bank account and routing number', 'share your banking information' ), 'credentials', 'bank_credentials', 28, 'Bank login or detailed account requests before verified employment can enable theft.', 'Do not share banking credentials. Payroll details should use a verified, secure HR process.' ),
    $rule( 'Password request', 'password-request', 'phrase', array( 'send your password', 'share your password', 'provide your password', 'email password', 'bank password' ), 'credentials', 'secret_credentials', 30, 'No legitimate recruiter needs your password.', 'Do not share passwords and change any password already disclosed.' ),
    $rule( 'OTP or security code request', 'otp-request', 'phrase', array( 'send the otp', 'share the otp', 'provide the otp', 'verification code you received', 'send security code', 'one-time password' ), 'credentials', 'secret_credentials', 30, 'One-time codes can let another person take over an account or authorize a transaction.', 'Never share an OTP or security code.' ),
    $rule( 'Government ID requested early', 'government-id-request', 'contextual', array( array( 'passport', 'driver license', 'government id', 'social security', 'ssn', 'national id' ), array( 'send', 'photo', 'copy', 'upload', 'provide' ) ), 'identity', 'identity_documents', 18, 'Identity documents requested before a verified hiring process can be used for identity theft.', 'Verify the employer and secure HR portal before sharing identity documents.' ),
    $rule( 'Urgent response pressure', 'urgency-pressure', 'phrase', array( 'act now', 'respond immediately', 'urgent response required', 'limited slots', 'offer expires today', 'must reply today', 'do not delay', 'last chance' ), 'pressure', 'urgency', 10, 'Pressure reduces the time available to verify a recruiter or notice inconsistencies.', 'Pause and verify independently, even if the sender says the opportunity will expire.' ),
    $rule( 'Threat or penalty pressure', 'threat-pressure', 'phrase', array( 'account will be frozen', 'lose your commission', 'legal action if you stop', 'penalty if you do not complete', 'credit score will be affected' ), 'pressure', 'threats', 17, 'Threats and invented penalties are coercive tactics, not normal recruitment behavior.', 'Stop contact and seek help from the platform, bank, or relevant authority.' ),
    $rule( 'Do not contact the company', 'avoid-verification', 'phrase', array( 'do not contact the company', 'do not call head office', 'keep this confidential from hr', 'do not verify this offer', 'do not tell anyone' ), 'communication', 'avoid_verification', 18, 'Discouraging independent verification is inconsistent with legitimate recruitment.', 'Contact the company using details found independently on its official website.' ),
    $rule( 'Generic email used as recruiter contact', 'generic-recruiter-email', 'regex', '/(?:recruit(?:er|ment)|human resources|hiring manager).{0,80}\b[a-z0-9._%+-]+@(gmail|yahoo|outlook|hotmail)\.(?:com|net)\b/isu', 'communication', 'generic_email', 8, 'A free email address does not prove fraud, but it deserves additional verification when presented as corporate recruiting.', 'Find the company’s official domain and confirm the recruiter through published contact details.' ),
    $rule( 'Reshipping job language', 'reshipping-job', 'phrase', array( 'package inspector', 'shipping coordinator from home', 'receive packages at your home', 'repackage and reship', 'quality control packages', 'parcel forwarding job' ), 'job_type', 'reshipping', 22, 'Reshipping jobs can involve stolen goods or purchases made with compromised accounts.', 'Do not receive or forward packages until the business and role are independently verified.' ),
    $rule( 'Mystery shopper check assignment', 'mystery-shopper-check', 'contextual', array( array( 'mystery shopper', 'secret shopper' ), array( 'check', 'money order', 'gift card', 'wire', 'evaluate' ) ), 'job_type', 'mystery_shopper', 20, 'Mystery shopper scams often send fake checks and direct victims to buy gift cards or wire money.', 'Do not use check proceeds or send purchased codes.' ),
    $rule( 'Personal assistant purchasing request', 'personal-assistant-purchase', 'contextual', array( array( 'personal assistant', 'virtual assistant' ), array( 'purchase', 'buy', 'vendor', 'errand', 'check', 'gift card' ) ), 'job_type', 'assistant_purchase', 17, 'Fake personal-assistant roles may ask candidates to move money or purchase items before any real work begins.', 'Refuse financial errands until the employer and payment have been independently verified.' ),
    $rule( 'Money transfer or mule activity', 'money-transfer-work', 'phrase', array( 'receive money into your account', 'transfer funds for clients', 'process payments through your bank', 'keep a percentage and forward', 'financial agent from home' ), 'payment', 'money_mule', 28, 'Jobs that use a personal bank account to receive and forward funds can involve fraud or money laundering.', 'Do not use your account to move money for an employer.' ),
    $rule( 'Shortened URL', 'shortened-url', 'shortened_url', '', 'links', 'shortened_link', 8, 'Short links hide the destination, making independent verification harder.', 'Do not open the link; navigate to the company website manually.' ),
    $rule( 'Messaging-app invitation link', 'messaging-url', 'messaging_url', '', 'links', 'messaging_link', 7, 'A messaging-app link can move the conversation to an account with limited identity verification.', 'Verify the recruiter before moving the conversation.' ),
    $rule( 'Free website-hosting domain', 'free-hosting-domain', 'free_hosting_url', '', 'links', 'unusual_domain', 8, 'A recruiting site hosted on a free website-builder domain deserves extra verification because established employers normally use their own domain.', 'Locate the employer’s official website independently and compare its careers page.' ),
    $rule( 'Unusual top-level domain', 'suspicious-tld', 'suspicious_tld', '', 'links', 'unusual_domain', 9, 'Some low-cost or unusual domains are disproportionately used for temporary scam sites, although the domain ending alone is not proof.', 'Find the employer website independently instead of using the supplied link.' ),
    $rule( 'Punycode domain', 'punycode-domain', 'punycode_url', '', 'links', 'lookalike_domain', 15, 'Punycode domains can be used to imitate familiar company names with lookalike characters.', 'Do not visit the link; type the known official company address manually.' ),
    $rule( 'IP-address link', 'ip-address-link', 'ip_url', '', 'links', 'raw_ip_link', 13, 'Legitimate recruiting pages rarely use a raw IP address instead of a recognizable company domain.', 'Avoid the link and locate the company’s careers page independently.' ),
);
